# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""renorm_ — in-place p-norm renormalization (Triton, Ascend).

Observable semantics reproduced from the on-device oracle (torch_npu aclnn
renorm_): each *slab* of `self` obtained by fixing the `dim` coordinate is
renormalized by the p-norm taken over the **complement** of `dim`; strict
`norm > maxnorm` gates the scale, and the transform is in-place on the original
strides (no permute / contiguous copy / temp allocation).

Two launch shapes are used:

* ``_renorm_r1_kernel`` — the dominant layout, where the complement collapses to
  a single ``(size, stride)`` pair (every contiguous tensor with one non-dim
  axis left after size-1 elimination, including all 2-D cases). Its argument
  list is just ``(X, K, N, s_dim, u0, p, maxnorm)`` plus constexprs.
* ``_renorm_kernel`` — the fully general collapsed-complement path (R > 1).

The op is launch-bound on this target (an 8 KB tensor and a 33 MB tensor measure
within a few microseconds of each other), so the wrapper keeps a
per-``(shape, strides, dtype, dim, p)`` plan holding the compiled kernel handle
and its invariant argument tail, and re-enters it through the compiled kernel's
own launch entry instead of re-running Triton's per-call dispatch. The tile
geometry (orientation, DMA width, single vs. two-pass) is derived from the layout
exactly as before; the plan only memoizes it.
"""

import triton
import triton.language as tl

# PMODE: 0 = p==0 (nonzero count), 1 = p==1 (sum |x|), 2 = p==2 (sqrt of sum sq),
#        3 = p==+inf (max |x|), 4 = p==-inf (min |x|), 5 = generic pow
_NEG_INF = float("-inf")
_POS_INF = float("inf")

_MAX_R = 8

# per-(shape, stride, dtype, dim, p) launch plan
_PLAN = {}

try:  # launch hooks installed by the runtime (kept as-is for faithful launches)
    from triton import knobs as _knobs

    _RT_KNOBS = _knobs.runtime
except Exception:  # pragma: no cover - older builds
    _RT_KNOBS = None


@triton.jit
def _rpow(x, y):
    """|x| ** y for x > 0 without a libdevice pow dependency."""
    return tl.exp2(y * tl.log2(x))


@triton.jit
def _comp_off(
    j, c0, u0, c1, u1, c2, u2, c3, u3, c4, u4, c5, u5, c6, u6, c7, u7, R: tl.constexpr
):
    """Offset (relative to a slab start) of complement linear index j.

    Complement dims are given outermost-first; the innermost (fastest varying)
    one is extracted first so consecutive j walk contiguous memory when the
    innermost complement stride is 1.
    """
    if R == 1:
        # single complement dim: affine, no runtime integer div/mod
        return j * u0
    rem = j
    off = j - j
    if R > 7:
        c = rem % c7
        rem = rem // c7
        off = off + c * u7
    if R > 6:
        c = rem % c6
        rem = rem // c6
        off = off + c * u6
    if R > 5:
        c = rem % c5
        rem = rem // c5
        off = off + c * u5
    if R > 4:
        c = rem % c4
        rem = rem // c4
        off = off + c * u4
    if R > 3:
        c = rem % c3
        rem = rem // c3
        off = off + c * u3
    if R > 2:
        c = rem % c2
        rem = rem // c2
        off = off + c * u2
    if R > 1:
        c = rem % c1
        rem = rem // c1
        off = off + c * u1
    if R > 0:
        c = rem % c0
        rem = rem // c0
        off = off + c * u0
    return off


@triton.jit
def _chunk_acc(xf, p_val, PMODE: tl.constexpr, AXIS: tl.constexpr):
    if PMODE == 2:
        return tl.sum(xf * xf, axis=AXIS)
    elif PMODE == 1:
        return tl.sum(tl.abs(xf), axis=AXIS)
    elif PMODE == 0:
        return tl.sum(tl.where(xf != 0.0, 1.0, 0.0), axis=AXIS)
    elif PMODE == 3:
        return tl.max(tl.abs(xf), axis=AXIS)
    elif PMODE == 4:
        return tl.min(tl.abs(xf), axis=AXIS)
    else:
        return tl.sum(_rpow(tl.abs(xf), p_val), axis=AXIS)


@triton.jit
def _chunk_nan(xf, AXIS: tl.constexpr):
    return tl.max(tl.where(xf != xf, 1.0, 0.0), axis=AXIS)


@triton.jit
def _norm_scale(acc, nanf, p_val, maxnorm, PMODE: tl.constexpr):
    if PMODE == 2:
        norm = tl.sqrt(acc)
    elif PMODE == 3 or PMODE == 4:
        norm = tl.where(nanf > 0.0, float("nan"), acc)
    elif PMODE == 0 or PMODE == 1:
        norm = acc
    else:
        norm = _rpow(acc, 1.0 / p_val)
    return tl.where(norm > maxnorm, maxnorm / norm, 1.0)


@triton.jit
def _renorm_r1_kernel(
    X,
    K,
    N,
    s_dim,
    u0,
    p_val,
    maxnorm,
    PMODE: tl.constexpr,
    ORIENT: tl.constexpr,
    BM: tl.constexpr,
    BJ: tl.constexpr,
    SINGLE: tl.constexpr,
    MASKED: tl.constexpr,
    INT64: tl.constexpr,
):
    """Complement collapses to one (size, stride) pair: off = i*s_dim + j*u0."""
    pid = tl.program_id(0)
    i = pid * BM + tl.arange(0, BM)
    jb = tl.arange(0, BJ)
    if INT64:
        i = i.to(tl.int64)
        jb = jb.to(tl.int64)
    di = i * s_dim
    other = 0.0
    if PMODE == 4:
        other = _POS_INF

    if SINGLE:
        base = jb * u0
        if ORIENT == 0:
            offs = di[:, None] + base[None, :]
            mask = (i < K)[:, None] & (jb < N)[None, :]
        else:
            offs = base[:, None] + di[None, :]
            mask = (jb < N)[:, None] & (i < K)[None, :]
        if MASKED:
            xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
        else:
            xf = tl.load(X + offs).to(tl.float32)
        if ORIENT == 0:
            acc = _chunk_acc(xf, p_val, PMODE, 1)
            nanf = acc
            if PMODE == 3 or PMODE == 4:
                nanf = _chunk_nan(xf, 1)
            scale = _norm_scale(acc, nanf, p_val, maxnorm, PMODE)
            y = xf * scale[:, None]
        else:
            acc = _chunk_acc(xf, p_val, PMODE, 0)
            nanf = acc
            if PMODE == 3 or PMODE == 4:
                nanf = _chunk_nan(xf, 0)
            scale = _norm_scale(acc, nanf, p_val, maxnorm, PMODE)
            y = xf * scale[None, :]
        if MASKED:
            tl.store(X + offs, y.to(X.dtype.element_ty), mask=mask)
        else:
            tl.store(X + offs, y.to(X.dtype.element_ty))
    else:
        zero = tl.zeros([BM], dtype=tl.float32)
        if PMODE == 4:
            acc = zero + _POS_INF
        else:
            acc = zero
        nanf = zero
        for k0 in range(0, N, BJ):
            if ORIENT == 0:
                offs = di[:, None] + (jb + k0)[None, :] * u0
                if MASKED:
                    mask = (i < K)[:, None] & (jb + k0 < N)[None, :]
                    xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
                else:
                    xf = tl.load(X + offs).to(tl.float32)
                part = _chunk_acc(xf, p_val, PMODE, 1)
            else:
                offs = (jb + k0)[:, None] * u0 + di[None, :]
                if MASKED:
                    mask = (jb + k0 < N)[:, None] & (i < K)[None, :]
                    xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
                else:
                    xf = tl.load(X + offs).to(tl.float32)
                part = _chunk_acc(xf, p_val, PMODE, 0)
            if PMODE == 3:
                acc = tl.maximum(acc, part)
            elif PMODE == 4:
                acc = tl.minimum(acc, part)
            else:
                acc = acc + part
            if PMODE == 3 or PMODE == 4:
                if ORIENT == 0:
                    nanf = tl.maximum(nanf, _chunk_nan(xf, 1))
                else:
                    nanf = tl.maximum(nanf, _chunk_nan(xf, 0))
        scale = _norm_scale(acc, nanf, p_val, maxnorm, PMODE)
        for k0 in range(0, N, BJ):
            if ORIENT == 0:
                offs = di[:, None] + (jb + k0)[None, :] * u0
                if MASKED:
                    mask = (i < K)[:, None] & (jb + k0 < N)[None, :]
                    xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
                else:
                    xf = tl.load(X + offs).to(tl.float32)
                y = xf * scale[:, None]
            else:
                offs = (jb + k0)[:, None] * u0 + di[None, :]
                if MASKED:
                    mask = (jb + k0 < N)[:, None] & (i < K)[None, :]
                    xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
                else:
                    xf = tl.load(X + offs).to(tl.float32)
                y = xf * scale[None, :]
            if MASKED:
                tl.store(X + offs, y.to(X.dtype.element_ty), mask=mask)
            else:
                tl.store(X + offs, y.to(X.dtype.element_ty))


@triton.jit
def _renorm_kernel(
    X,
    K,
    N,
    s_dim,
    c0,
    u0,
    c1,
    u1,
    c2,
    u2,
    c3,
    u3,
    c4,
    u4,
    c5,
    u5,
    c6,
    u6,
    c7,
    u7,
    p_val,
    maxnorm,
    R: tl.constexpr,
    PMODE: tl.constexpr,
    ORIENT: tl.constexpr,
    BM: tl.constexpr,
    BJ: tl.constexpr,
    SINGLE: tl.constexpr,
    MASKED: tl.constexpr,
    INT64: tl.constexpr,
):
    pid = tl.program_id(0)
    i = pid * BM + tl.arange(0, BM)
    jb = tl.arange(0, BJ)
    if INT64:
        i = i.to(tl.int64)
        jb = jb.to(tl.int64)
    di = i * s_dim
    other = 0.0
    if PMODE == 4:
        other = _POS_INF

    if SINGLE:
        base = _comp_off(
            jb, c0, u0, c1, u1, c2, u2, c3, u3, c4, u4, c5, u5, c6, u6, c7, u7, R
        )
        if ORIENT == 0:
            offs = di[:, None] + base[None, :]
        else:
            offs = base[:, None] + di[None, :]
        if MASKED:
            if ORIENT == 0:
                mask = (i < K)[:, None] & (jb < N)[None, :]
            else:
                mask = (jb < N)[:, None] & (i < K)[None, :]
            xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
        else:
            xf = tl.load(X + offs).to(tl.float32)
        if ORIENT == 0:
            acc = _chunk_acc(xf, p_val, PMODE, 1)
        else:
            acc = _chunk_acc(xf, p_val, PMODE, 0)
        nanf = acc
        if PMODE == 3 or PMODE == 4:
            if ORIENT == 0:
                nanf = _chunk_nan(xf, 1)
            else:
                nanf = _chunk_nan(xf, 0)
        scale = _norm_scale(acc, nanf, p_val, maxnorm, PMODE)
        if ORIENT == 0:
            y = xf * scale[:, None]
        else:
            y = xf * scale[None, :]
        if MASKED:
            tl.store(X + offs, y.to(X.dtype.element_ty), mask=mask)
        else:
            tl.store(X + offs, y.to(X.dtype.element_ty))
    else:
        zero = tl.zeros([BM], dtype=tl.float32)
        if PMODE == 4:
            acc = zero + _POS_INF
        else:
            acc = zero
        nanf = zero
        for k0 in range(0, N, BJ):
            j = jb + k0
            base = _comp_off(
                j, c0, u0, c1, u1, c2, u2, c3, u3, c4, u4, c5, u5, c6, u6, c7, u7, R
            )
            if ORIENT == 0:
                offs = di[:, None] + base[None, :]
            else:
                offs = base[:, None] + di[None, :]
            if MASKED:
                if ORIENT == 0:
                    mask = (i < K)[:, None] & (j < N)[None, :]
                else:
                    mask = (j < N)[:, None] & (i < K)[None, :]
                xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
            else:
                xf = tl.load(X + offs).to(tl.float32)
            if ORIENT == 0:
                part = _chunk_acc(xf, p_val, PMODE, 1)
            else:
                part = _chunk_acc(xf, p_val, PMODE, 0)
            if PMODE == 3:
                acc = tl.maximum(acc, part)
            elif PMODE == 4:
                acc = tl.minimum(acc, part)
            else:
                acc = acc + part
            if PMODE == 3 or PMODE == 4:
                if ORIENT == 0:
                    nanf = tl.maximum(nanf, _chunk_nan(xf, 1))
                else:
                    nanf = tl.maximum(nanf, _chunk_nan(xf, 0))
        scale = _norm_scale(acc, nanf, p_val, maxnorm, PMODE)
        for k0 in range(0, N, BJ):
            j = jb + k0
            base = _comp_off(
                j, c0, u0, c1, u1, c2, u2, c3, u3, c4, u4, c5, u5, c6, u6, c7, u7, R
            )
            if ORIENT == 0:
                offs = di[:, None] + base[None, :]
            else:
                offs = base[:, None] + di[None, :]
            if MASKED:
                if ORIENT == 0:
                    mask = (i < K)[:, None] & (j < N)[None, :]
                else:
                    mask = (j < N)[:, None] & (i < K)[None, :]
                xf = tl.load(X + offs, mask=mask, other=other).to(tl.float32)
            else:
                xf = tl.load(X + offs).to(tl.float32)
            if ORIENT == 0:
                y = xf * scale[:, None]
            else:
                y = xf * scale[None, :]
            if MASKED:
                tl.store(X + offs, y.to(X.dtype.element_ty), mask=mask)
            else:
                tl.store(X + offs, y.to(X.dtype.element_ty))


@triton.jit
def _renorm_elem_kernel(
    X, numel, p_val, maxnorm, PMODE: tl.constexpr, BLOCK: tl.constexpr
):
    """N == 1 degenerate layout: every slab holds one element, norm = |x|."""
    pid = tl.program_id(0)
    off = pid * BLOCK + tl.arange(0, BLOCK)
    m = off < numel
    x = tl.load(X + off, mask=m, other=0.0).to(tl.float32)
    if PMODE == 0:
        norm = tl.where(x != 0.0, 1.0, 0.0)
    elif PMODE == 3 or PMODE == 4:
        norm = tl.where(x != x, float("nan"), tl.abs(x))
    else:
        norm = tl.abs(x)
    scale = tl.where(norm > maxnorm, maxnorm / norm, 1.0)
    tl.store(X + off, (x * scale).to(X.dtype.element_ty), mask=m)


def _mode(p):
    if p == 0.0:
        return 0
    if p == 1.0:
        return 1
    if p == 2.0:
        return 2
    if p == _POS_INF:
        return 3
    if p == _NEG_INF:
        return 4
    return 5


def _complement_pairs(shape, stride, d):
    """Collapsed (size, stride) list of the dims other than dim `d`, outer->inner."""
    pairs = []
    for k in range(len(shape)):
        if k == d:
            continue
        s = shape[k]
        t = stride[k]
        if s == 1:
            continue
        if pairs and pairs[-1][1] == t * s:
            # adjacent in memory: merged dim must keep the inner stride
            pairs[-1] = (pairs[-1][0] * s, t)
        else:
            pairs.append((s, t))
    if len(pairs) > 1:
        for k, (_s, t) in enumerate(pairs):
            if t == 1:
                if k != len(pairs) - 1:
                    pairs.append(pairs.pop(k))
                break
    return pairs


def _make_launcher(kernel, grid, mid, cxs):
    """Memoized launch entry for one specialization.

    ``kernel`` is the CompiledKernel returned by the first (normal) JIT launch;
    ``mid`` are the invariant integer arguments and ``cxs`` the constexpr values
    (Triton's bound-argument list includes constexprs, so the low-level launch
    entry takes them too). Only the tensor and the two scalars vary per call.

    The entry goes straight to the generated C launch function: that skips both
    Triton's per-call dispatch and the backend launcher object's ``__call__``
    (environment checks, an ``import triton`` statement and a module attribute
    store per launch). Launch hooks are passed through unless the installed
    hook chains are empty, in which case they could do nothing anyway and the
    per-call launch-metadata dict is not built.
    """
    launcher = kernel.renorm_
    c_launch = launcher.launch
    fn = kernel.function
    pm = kernel.packed_metadata
    g0 = grid[0]
    g1 = grid[1] if len(grid) > 1 else 1
    g2 = grid[2] if len(grid) > 2 else 1
    grid3 = (g0, g1, g2)

    from triton.runtime import driver as _driver

    active = _driver.active
    dev = active.get_current_device()
    if _RT_KNOBS is not None:
        enter = _RT_KNOBS.launch_enter_hook
        exit_hook = _RT_KNOBS.launch_exit_hook
    else:  # pragma: no cover
        enter = None
        exit_hook = None

    # A triton.knobs.HookChain with an empty `calls` list does nothing when
    # invoked, so passing None for it disables no installed instrumentation.
    idle_hooks = not getattr(enter, "calls", ()) and not getattr(exit_hook, "calls", ())

    if idle_hooks:

        def launch_fast_idle(x, pv, mv):
            stream = active.get_current_stream(dev)
            c_launch(
                g0, g1, g2, stream, fn, pm, None, None, None, x, *mid, pv, mv, *cxs
            )

        return launch_fast_idle

    else:

        def launch_fast_hooked(x, pv, mv):
            stream = active.get_current_stream(dev)
            args = (x, *mid, pv, mv, *cxs)
            lm = kernel.launch_metadata(grid3, stream, *args)
            c_launch(g0, g1, g2, stream, fn, pm, lm, enter, exit_hook, *args)

        return launch_fast_hooked


def _plan(x, pv, dim, mv, key):
    """Validate the arguments, derive the launch geometry and memoize it."""
    ndim = x.dim()
    if ndim < 2:
        raise RuntimeError("renorm_: The self tensor must have at least 2 dimensions.")
    d = int(dim)
    if d < 0:
        d += ndim
    if d < 0 or d >= ndim:
        raise RuntimeError(
            "renorm_: dim range only support [-dimNum, dimNum - 1], but now dim is [%d]."
            % int(dim)
        )
    if not (pv > 0.0):
        raise RuntimeError(
            "renorm_: p only support positive values, but now p is [%f]." % pv
        )

    shape = x.shape
    K = shape[d]
    numel = x.numel()
    if numel == 0 or K == 0:
        return x

    s_dim = x.stride(d)
    pmode = _mode(pv)
    pairs = _complement_pairs(shape, x.stride(), d)
    R = len(pairs)
    if R > _MAX_R:
        raise RuntimeError("renorm_: unsupported layout (too many dims)")
    N = 1
    for s, _t in pairs:
        N *= s

    if R == 0:
        # complement holds a single element: norm is |x| itself
        BLOCK = 256
        grid = (triton.cdiv(numel, BLOCK),)
        kernel = _renorm_elem_kernel[grid](x, numel, pv, mv, PMODE=pmode, BLOCK=BLOCK)
        _PLAN[key] = _make_launcher(kernel, grid, (numel,), (pmode, BLOCK))
        return x

    packed = [(1, 0)] * _MAX_R
    for k, pr in enumerate(pairs):
        packed[k] = pr

    inner_stride = pairs[-1][1]
    orient = 0 if (inner_stride == 1 or s_dim != 1) else 1

    esz = x.element_size()
    npk = triton.next_power_of_2(N)
    npk_k = triton.next_power_of_2(K)
    if orient == 1:
        # slab axis is memory-contiguous: keep each row DMA wide (>= 256 B)
        want = max(16, 256 // esz)
        BM = min(npk_k, want)
        if K // BM < 4 and BM > 8:
            BM = max(8, npk_k // 4)
        BJ = max(1, min(npk, 8192 // BM))
        single = npk <= BJ
    else:
        # complement inner axis is memory-contiguous: BJ is the wide run
        if npk <= 2048:
            single = True
            BJ = max(16, npk)
            BM = max(1, min(npk_k, 4096 // BJ, 64))
        else:
            single = False
            BJ = 1024
            BM = max(1, min(npk_k, 8, 64))
    if BM == 1:
        orient = 0

    masked = (K % BM != 0) or (N % BJ != 0)
    grid = (triton.cdiv(K, BM),)
    int64 = numel > 2**31 - 1

    if R == 1:
        u0 = packed[0][1]
        kernel = _renorm_r1_kernel[grid](
            x,
            K,
            N,
            s_dim,
            u0,
            pv,
            mv,
            PMODE=pmode,
            ORIENT=orient,
            BM=BM,
            BJ=BJ,
            SINGLE=single,
            MASKED=masked,
            INT64=int64,
        )
        _PLAN[key] = _make_launcher(
            kernel,
            grid,
            (K, N, s_dim, u0),
            (pmode, orient, BM, BJ, single, masked, int64),
        )
        return x

    _renorm_kernel[grid](
        x,
        K,
        N,
        s_dim,
        packed[0][0],
        packed[0][1],
        packed[1][0],
        packed[1][1],
        packed[2][0],
        packed[2][1],
        packed[3][0],
        packed[3][1],
        packed[4][0],
        packed[4][1],
        packed[5][0],
        packed[5][1],
        packed[6][0],
        packed[6][1],
        packed[7][0],
        packed[7][1],
        pv,
        mv,
        R=R,
        PMODE=pmode,
        ORIENT=orient,
        BM=BM,
        BJ=BJ,
        SINGLE=single,
        MASKED=masked,
        INT64=int64,
    )
    return x


def renorm_(self, p, dim, maxnorm):
    x = self
    pv = float(p)
    mv = float(maxnorm)
    key = (x.shape, x.stride(), x.dtype, int(dim), pv)
    launch = _PLAN.get(key)
    if launch is not None:
        launch(x, pv, mv)
        return x
    return _plan(x, pv, dim, mv, key)
